// Local APK signing utility; Android apksig is a caller-provided build dependency.
import com.android.apksig.*;import java.io.*;import java.security.*;import java.security.cert.X509Certificate;import java.util.*;
public final class SignMessages {
 public static void main(String[] a)throws Exception{String value=System.getenv("CARUSO_MESSAGES_SIGNING_PASSWORD");if(value==null)throw new IllegalStateException("Set signing password in environment");char[] password=value.toCharArray();KeyStore store=KeyStore.getInstance("PKCS12");try(InputStream in=new FileInputStream(a[0])){store.load(in,password);}PrivateKey key=(PrivateKey)store.getKey("messages",password);X509Certificate cert=(X509Certificate)store.getCertificate("messages");ApkSigner.SignerConfig config=new ApkSigner.SignerConfig.Builder("messages",key,Collections.singletonList(cert)).build();new ApkSigner.Builder(Collections.singletonList(config)).setInputApk(new File(a[1])).setOutputApk(new File(a[2])).setMinSdkVersion(26).setV1SigningEnabled(true).setV2SigningEnabled(true).setV3SigningEnabled(true).setV4SigningEnabled(false).build().sign();ApkVerifier.Result result=new ApkVerifier.Builder(new File(a[2])).setMinCheckedPlatformVersion(26).build().verify();Arrays.fill(password,'\0');if(!result.isVerified())throw new IllegalStateException("APK signature verification failed");System.out.println("Messages APK signature verified: v1="+result.isVerifiedUsingV1Scheme()+", v2="+result.isVerifiedUsingV2Scheme()+", v3="+result.isVerifiedUsingV3Scheme());}
}
